---GetCountdownDescrByCd 根据倒计时秒获取倒计时文字描述
---@param second integer @ 秒数
---@return string @ 倒计时的描述
function GachaCoinQuestUtils.GetCountdownDescrByCd(second)
    local s2m, m2h, h2d = 60, 60, 24

    if s2m > second then
        return localize('小于1分钟')
    else
        local totald = Mathf.Floor(second / (s2m * m2h * h2d))
        local totalh = Mathf.Floor(second / (s2m * m2h))
        local totalm = Mathf.Floor(second / s2m)

        local d = totald
        local h = totalh - totald * h2d
        local m = totalm - totalh * m2h
        -- local s = second - totalm * s2m

        local descr = ''
        local part = 2
        local timeConfig = {
            {time = d, descr = localize('天')},
            {time = h, descr = localize('小时')},
            {time = m, descr = localize('分钟')},
            -- {timeType = s, descr = localize('秒')},
        }

        for _, timeInfo in ipairs(timeConfig) do
            if 0 < timeInfo.time then
                descr = descr .. timeInfo.time .. timeInfo.descr
                part = part - 1
                if 0 >= part then
                    break
                end
            end
        end

        return descr
    end
end

