---IsQuestUnlock 判断关卡是否解锁
---@param questId integer @ 关卡id
---@param passedQuestId integer @ 通过的关卡id
function GachaCoinQuestUtils.IsQuestUnlock(questId, passedQuestId)
    if questId <= passedQuestId + 1 then
        -- 小于直接返回
        return true
    else
        -- 大于 判断是否是挑战关卡
        if GCQConstants.Defines.QuestType.Challenge == GachaCoinQuestUtils.GetGachaCoinQuestTypeById(questId) then
            local nquestId = GachaCoinQuestUtils.GetNQuestIdByCQuestId(questId)
            if nil ~= nquestId then
                return nquestId <= passedQuestId
            else
                -- 未找到挑战关卡对应的普通关卡id
                return false
            end
        else
            -- 不是挑战关卡 未解锁
            return false
        end
    end
end

---IsCQuestUnlock 判断挑战模式关卡是否解锁
---@param questId integer @ 关卡id
---@param passedQuestId integer @ 通过的关卡id
function GachaCoinQuestUtils.IsCQuestUnlock(questId, passedQuestId)
    local nquestId = questId
    if GCQConstants.Defines.QuestType.Challenge == GachaCoinQuestUtils.GetGachaCoinQuestTypeById(questId) then
        nquestId = GachaCoinQuestUtils.GetNQuestIdByCQuestId(questId)
    end
    return nquestId <= passedQuestId
end

