---GetFormattedNumber 获取格式化的数字
---@param number number @ 数字
---@param keta integer @ 位数不满自动填充0 例如01 002 0003
---@return string @ 格式化后的数字
function GachaCoinQuestUtils.GetFormattedNumber(number, keta)
    local mark = 10 ^ (keta - 1)
    if number >= mark then return tostring(number) end

    -- 位数未满 填充0
    local fixedNumber = tostring(number)
    for i = keta, 2 do
        if 10 ^ (keta - 1) > number then
            fixedNumber = '0' .. fixedNumber
        end
    end

    return fixedNumber
end

