---GetChallengeTaskDescr 获取挑战模式任务描述
---@param taskId integer @ 任务id
---@return string @ 任务描述
function GachaCoinQuestUtils.GetChallengeTaskDescr_(taskId)
    local taskDescr = ''
    local taskConfig = GachaCoinQuestUtils.GetVoById(AutoIds.IdSetting704, taskId)
    if nil ~= taskConfig then
        local taskType = checkInt(taskConfig.conditionType)
        local taskTypeConfig = GachaCoinQuestUtils.GetVoById(AutoIds.IdSetting705, taskType)

        local descr = taskTypeConfig.condition
        local mark = '_target_num_'

        local descr_ = parse_strings(descr, mark)
        local targetNum_ = parse_strings(taskConfig.conditionNum, ';')

        for index, value in ipairs(descr_) do
            taskDescr = taskDescr .. value
            if #descr_ > index then
                taskDescr = taskDescr .. tostring(targetNum_[index])
            end
        end
    end
    return taskDescr
end

