---GetQuestCostInfo 获取关卡的消耗信息
---@param questId integer @ 关卡id
---@return integer, integer @ 消耗的道具id,消耗的道具数量
function GachaCoinQuestUtils.GetQuestCostInfo(questId)
    local questConfig = GachaCoinQuestUtils.GetGachaCoinQuestConfigById(questId)
    if nil ~= questConfig then
        local costGoodsId = checkInt(questConfig.costItem)
        local costGoodsAmount = checkInt(questConfig.costNumLose)
        return costGoodsId, costGoodsAmount
    else
        return nil, 0
    end
end


